CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE sqlite_sequence(name,seq);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "is_admin" tinyint(1) not null default '0');
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" varchar not null, "queue" varchar not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE INDEX "failed_jobs_connection_queue_failed_at_index" on "failed_jobs" ("connection", "queue", "failed_at");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE TABLE IF NOT EXISTS "cities" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "province" varchar not null, "classification" varchar, "bps_code" varchar, "kecamatan_count" integer, "created_at" datetime, "updated_at" datetime);
CREATE UNIQUE INDEX "cities_slug_unique" on "cities" ("slug");
CREATE INDEX "cities_province_index" on "cities" ("province");
CREATE UNIQUE INDEX "cities_bps_code_unique" on "cities" ("bps_code");
CREATE TABLE IF NOT EXISTS "kecamatans" ("id" integer primary key autoincrement not null, "city_id" integer not null, "name" varchar not null, "slug" varchar not null, "bps_code" varchar, "created_at" datetime, "updated_at" datetime, foreign key("city_id") references "cities"("id") on delete cascade);
CREATE UNIQUE INDEX "kecamatans_city_id_slug_unique" on "kecamatans" ("city_id", "slug");
CREATE UNIQUE INDEX "kecamatans_city_id_bps_code_unique" on "kecamatans" ("city_id", "bps_code");
CREATE TABLE IF NOT EXISTS "settings" ("id" integer primary key autoincrement not null, "key" varchar not null, "value" text, "created_at" datetime, "updated_at" datetime);
CREATE UNIQUE INDEX "settings_key_unique" on "settings" ("key");
CREATE TABLE IF NOT EXISTS "catalog_items" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "category" varchar not null, "source_order" integer not null, "review_required" tinyint(1) not null default '0', "review_note" text, "created_at" datetime, "updated_at" datetime);
CREATE UNIQUE INDEX "catalog_items_category_source_order_unique" on "catalog_items" ("category", "source_order");
CREATE UNIQUE INDEX "catalog_items_slug_unique" on "catalog_items" ("slug");
CREATE UNIQUE INDEX "catalog_items_category_name_unique" on "catalog_items" ("category", "name");
CREATE INDEX "catalog_items_category_index" on "catalog_items" ("category");
CREATE UNIQUE INDEX "cities_province_classification_name_unique" on "cities" ("province", "classification", "name");
CREATE TABLE IF NOT EXISTS "catalog_contents" ("id" integer primary key autoincrement not null, "catalog_item_id" integer not null, "status" varchar not null default 'review', "fields" text not null, "generated_at" datetime, "edited_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("catalog_item_id") references "catalog_items"("id") on delete cascade);
CREATE INDEX "catalog_contents_status_catalog_item_id_index" on "catalog_contents" ("status", "catalog_item_id");
CREATE UNIQUE INDEX "catalog_contents_catalog_item_id_unique" on "catalog_contents" ("catalog_item_id");
CREATE INDEX "catalog_contents_status_index" on "catalog_contents" ("status");
CREATE TABLE IF NOT EXISTS "articles" ("id" integer primary key autoincrement not null, "title" varchar not null, "slug" varchar not null, "excerpt" text, "content" text not null, "reading_time" integer, "word_count" integer not null default '0', "status" varchar not null default 'draft', "featured_image" varchar, "faqs" text, "seo_title" varchar, "meta_description" varchar, "catalog_item_id" integer, "city_id" integer, "kecamatan_id" integer, "published_at" datetime, "created_at" datetime, "updated_at" datetime, "image_brief" text, foreign key("catalog_item_id") references "catalog_items"("id") on delete set null, foreign key("city_id") references "cities"("id") on delete set null, foreign key("kecamatan_id") references "kecamatans"("id") on delete set null);
CREATE INDEX "articles_new_status_published_at_index" on "articles" ("status", "published_at");
CREATE UNIQUE INDEX "articles_new_slug_unique" on "articles" ("slug");
CREATE INDEX "articles_new_status_index" on "articles" ("status");
CREATE INDEX "articles_new_published_at_index" on "articles" ("published_at");
CREATE TABLE IF NOT EXISTS "articles_old" ("id" integer primary key autoincrement not null, "title" varchar not null, "slug" varchar not null, "excerpt" text, "content" text not null, "reading_time" integer, "word_count" integer not null default '0', "status" varchar not null default 'draft', "featured_image" varchar, "faqs" text, "seo_title" varchar, "meta_description" varchar, "catalog_item_id" integer, "city_id" integer, "kecamatan_id" integer, "published_at" datetime, "created_at" datetime, "updated_at" datetime, "image_brief" text, foreign key("catalog_item_id") references "catalog_items_legacy"("id") on delete set null, foreign key("city_id") references "cities"("id") on delete set null, foreign key("kecamatan_id") references "kecamatans"("id") on delete set null);
CREATE INDEX "articles_old_status_published_at_index" on "articles_old" ("status", "published_at");
CREATE UNIQUE INDEX "articles_old_slug_unique" on "articles_old" ("slug");
CREATE INDEX "articles_old_status_index" on "articles_old" ("status");
CREATE INDEX "articles_old_published_at_index" on "articles_old" ("published_at");
